function miniCal(){const first=new Date(miniYear,miniMonth,1),count=new Date(miniYear,miniMonth+1,0).getDate(),offset=(first.getDay()+6)%7;const title=first.toLocaleDateString('cs-CZ',{month:'long',year:'numeric'});return `<div class="calendar-card"><div class="mini-cal-head"><span>${title[0].toUpperCase()+title.slice(1)}</span><div class="cal-controls"><button data-month="-1" aria-label="Předchozí měsíc">‹</button><button data-month="1" aria-label="Další měsíc">›</button></div></div><div class="mini-calendar">${['PO','ÚT','ST','ČT','PÁ','SO','NE'].map(d=>`<span class="dow">${d}</span>`).join('')}${'<span class="blank"></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const date=`${miniYear}-${String(miniMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,ev=calendarItems().filter(e=>e.date===date);return `<button data-caldate="${date}" class="${date===todayISO()?'current ':''}${ev.length?'event ':''}${ev.some(e=>e.kind==='volno'||e.allDay===true)?'holiday':''}" aria-label="${dateLabel(date)}${ev.length?': '+esc(ev.map(e=>e.title).join(', ')):''}" ${date===todayISO()?'aria-current="date"':''}>${i+1}</button>`}).join('')}</div><div class="cal-legend"><span class="tiny-dot"></span> Školní akce a důležité termíny</div></div>`}
