function teachers(){return head('LIDÉ NA BETLÉMSKÉ','Najdi svého vyučujícího.','Kontakty, kabinety, vyučované předměty a rozvrhy přehledně podle abecedy.')+`<div class="toolbar"><label class="search">${icon('search')}<input id="teacher-search" type="search" placeholder="Jméno, předmět, kabinet…" aria-label="Hledat vyučujícího" value="${esc(teacherQuery)}"></label><select id="teacher-filter" aria-label="Filtrovat učitele"><option value="all">Všichni vyučující</option><option value="present">Ve škole dle rozvrhu</option><option value="away">Mimo školu dle rozvrhu</option><option value="mine">Vyučující ${myClass}</option></select></div>${presenceLegend()}<div id="teacher-count" class="eyebrow" style="margin:22px 0 15px;font-size:9px"></div><div class="teacher-grid" id="teacher-results"></div>`}
function filterTeachers(){document.querySelectorAll('#teacher-results video').forEach(v=>pauseTeacherVideo(v));const ts=[...data.teachers].sort((a,b)=>a.last.localeCompare(b.last,'cs')).filter(t=>norm([t.name,t.room,...t.subjects,...t.subjects.map(s=>fullSubjects[s]||s)].join(' ')).includes(norm(teacherQuery))).filter(t=>teacherFilter==='present'?teacherPresence(t).cls==='yes':teacherFilter==='away'?teacherPresence(t).cls==='no':teacherFilter==='mine'?t.schedule.some(l=>inClass(l,myClass)):true);$('#teacher-results').innerHTML=ts.length?ts.map(teacherCard).join(''):'<p class="empty">Žádný vyučující neodpovídá hledání.</p>';$('#teacher-count').textContent=ts.length===1?'1 VYUČUJÍCÍ':`${ts.length} VYUČUJÍCÍCH`;}
function scheduleDuty(duty){
 const interval=BetlemskaPortal.dutyInterval(duty,hours),format=m=>`${Math.floor(m/60)}:${String(m%60).padStart(2,'0')}`;
 const time=interval?(interval.start===null?'do '+format(interval.end):format(interval.start)+'–'+format(interval.end)):'';
 return `<div class="schedule-duty duty-${duty.kind}" data-duty-start="${interval?.start??''}" data-duty-end="${interval?.end??''}"><b>${esc(duty.label)}</b><span>${duty.before?'Před '+(duty.hour+1)+'. hodinou':(duty.hour+1)+'. hodina'}</span><small>${time}</small><span class="duty-live-label" hidden>Právě teď</span></div>`;
}
